def transform(grid):
    h, w = len(grid), len(grid[0])

    row_seps = [r for r in range(h) if len(set(grid[r])) == 1]
    col_seps = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def intervals(n, seps):
        parts = []
        start = 0
        for s in seps:
            if start < s:
                parts.append((start, s))
            start = s + 1
        if start < n:
            parts.append((start, n))
        return parts

    row_parts = intervals(h, row_seps)
    col_parts = intervals(w, col_seps)

    # Find the background color from cells, excluding the separator lines.
    counts = {}
    for r0, r1 in row_parts:
        for c0, c1 in col_parts:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    color = grid[r][c]
                    counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)

    result = []
    for r0, r1 in row_parts:
        out_row = []
        for c0, c1 in col_parts:
            marks = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            out_row.append(1 if marks >= 2 else background)
        result.append(out_row)
    return result
